package com.edgeos.launcher; import android.app.*;import android.os.*;import android.graphics.*;import android.content.*;import android.view.*;import android.widget.*;import java.util.*;
public class AppPickerActivity extends Activity{public void onCreate(Bundle b){super.onCreate(b);ArrayList<AppInfo>a=AppRepository.load(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(20,30,20,20);r.setBackgroundColor(0xFF111318);r.addView(Ui.text(this,"EDGE OS",30,Color.WHITE),new LinearLayout.LayoutParams(-1,70));for(AppInfo x:a){TextView t=Ui.text(this,x.label,17,Color.WHITE);t.setGravity(Gravity.CENTER_VERTICAL|Gravity.LEFT);t.setPadding(16,0,0,0);t.setOnClickListener(v->{Intent i=getPackageManager().getLaunchIntentForPackage(x.pkg);if(i!=null)startActivity(i);});r.addView(t,new LinearLayout.LayoutParams(-1,52));}ScrollView s=new ScrollView(this);s.addView(r);setContentView(s);}}
